            rail = '''<aside class="sandbox-rail"><div class="rail-logo">Red Fox<small>MARKET INTELLIGENCE</small></div><span class="rail-live">LIVE</span><div class="rail-section">Workspace</div><nav class="rail-nav"><button class="active" onclick="sandboxTab('all',this)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>Market board</button><button onclick="sandboxTab('today',this)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>Today's games <span class="rail-count" id="rail-today">—</span></button><button onclick="sandboxTab('live-recent',this)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 12h4l3-7 4 14 3-7h4"/></svg>Live &amp; recent</button></nav><div class="rail-section">Library</div><nav class="rail-nav"><button onclick="openSignalGuide()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="12" cy="12" r="9"/><path d="M9.8 9a2.4 2.4 0 1 1 4.1 1.7c-.9.9-1.9 1.4-1.9 2.8M12 17h.01"/></svg>Signal terms</button><button onclick="sandboxDataHealth()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M4 19V5M4 19h16"/><path d="m7 15 4-4 3 2 5-6"/></svg>Data health</button></nav><div class="rail-section">Saved games <span class="rail-count" id="saved-count">0</span></div><div class="saved-games" id="saved-games"><div class="saved-empty">Star a market on the board to keep it here.</div></div><div class="rail-foot">Market intelligence, organized around evidence—not noise.</div></aside>'''
